sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	test.TestCase_RestApiOperation(
		'Deployer Target API',
		'Get Transactions',
		null,
		null,
		'User is not authenticated');
	
	
	var testdata = new x_snc_devtools.TestDataAPI('ATF.DEPLOYER');
	var strPassword = x_snc_devtools.GetRandomNumericToken(30);
	
	var strUserNoRolesSysId = testdata.CreateUser('No Roles',[],false,'',strPassword);
	var grUserNoRoles = x_snc_devtools.GetUserRecord(strUserNoRolesSysId);
	var oBasicAuth = {
		username: x_snc_devtools.GetStringValue(grUserNoRoles.user_name),
		password: strPassword
	};
	
	test.TestCase_RestApiOperation(
		'Deployer Target API',
		'Get Transactions',
		oBasicAuth,
		null,
		'User Not Authorized');
	
	var strUserTargetApiSysId = testdata.CreateUser('Target API',['x_snc_deployer.api_target'],false,'',strPassword);
	var grUserTargetApi = x_snc_devtools.GetUserRecord(strUserTargetApiSysId);
	var oBasicAuth = {
		username: x_snc_devtools.GetStringValue(grUserTargetApi.user_name),
		password: strPassword
	};
	
	test.TestCase_RestApiOperation(
		'Deployer Target API',
		'Get Transactions',
		oBasicAuth,
		null,
		'SUCCESS');	
	
	
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
